// iphone-mesh.js — baked iPhone 17 Pro model (generated from "iPhone 17 Pro.glb", do not edit)
// Two indexed batches in one model space: centered on bbox center, max dim = 2.0,
// +Y up, screen faces +Z. Thickness ratio (z extent / 2.0) = 0.0886.
// solid: pos Float32Array (xyz), nrm Float32Array (normalized), rgb Float32Array
//   (sRGB 0..1 per-vertex; baked from baseColorFactors + averaged textures), idx Uint16Array.
// screen: pos/nrm/uv/idx + tex — the OLED face; uv top-left-origin V, use as-is with
//   texImage2D(<img>) without UNPACK_FLIP_Y; tex is a 512px-max JPEG q70 data URI
//   (wallpaper); render it unlit/emissive. Screen normals all (0,0,1).
(function () {
  function b(s) {
    var d = atob(s), u = new Uint8Array(d.length);
    for (var i = 0; i < d.length; i++) u[i] = d.charCodeAt(i);
    return u;
  }
  var PS = 30000.0;
  // -- solid --
  var sp16 = new Int16Array(b("").buffer);
  var sn8 = new Int8Array(b("").buffer);
  var sr8 = new Uint8Array(b(""));
  var sidx = new Uint16Array(b("").buffer);
  var sn = sp16.length / 3;
  var spos = new Float32Array(sn * 3), snrm = new Float32Array(sn * 3), srgb = new Float32Array(sn * 3);
  for (var i = 0; i < sn * 3; i++) { spos[i] = sp16[i] / PS; snrm[i] = sn8[i] / 127; srgb[i] = sr8[i] / 255; }
  // -- screen --
  var zp16 = new Int16Array(b("").buffer);
  var zu16 = new Uint16Array(b("").buffer);
  var zidx = new Uint16Array(b("").buffer);
  var zn = zp16.length / 3;
  var zpos = new Float32Array(zn * 3), znrm = new Float32Array(zn * 3), zuv = new Float32Array(zn * 2);
  for (var i = 0; i < zn * 3; i++) zpos[i] = zp16[i] / PS;
  for (var i = 0; i < zn; i++) { znrm[i * 3] = 0; znrm[i * 3 + 1] = 0; znrm[i * 3 + 2] = 1; }
  for (var i = 0; i < zn * 2; i++) zuv[i] = zu16[i] / 65535;
  window.IPHONE_MESH = {
    solid: { pos: spos, nrm: snrm, rgb: srgb, idx: sidx, vertCount: sn, triCount: sidx.length / 3 },
    screen: {
      pos: zpos, nrm: znrm, uv: zuv, idx: zidx, vertCount: zn, triCount: zidx.length / 3,
      tex: "data:image/jpeg;base64,"
    },
    thickness: 0.0886
  };
})();
